import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;
/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing rabbits and foxes.
 *
 * @version 2.0
 */
public class Simulator
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // The default dimensions
    private static final int DEFAULT_WIDTH = 120;
    private static final int DEFAULT_DEPTH = 80;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    // List of animals in the field.
    private List<Actor> animals;
    private List<Actor> plants;
    // The current state of the field.
    private Field field;

    private SimulatorClock clock;
    private WeatherHandler weatherHandler;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private SimulatorView view;
    // creates animal factories
    private AnimalFactoryProducer producer;
    // handles the simulation of the disease
    private DiseaseHandler diseaseHandler;
    // swing component dashboard
    private Dashboard dashboard;
    // generator for the initial terrain and population
    private PopulationGenerator populationGenerator;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTORS
    //////////////////////////////////////////////////////////////*/

    /**
     * Construct a simulation field with default size.
     */
    public Simulator() throws Exception
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * 
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width) throws Exception
    {
        if(depth % 20 != 0 || width % 20 != 0) {
            throw new Exception("Depth and Width must be factors of 20");
        }

        if(width <= 0 || depth <= 0) {
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        animals = new ArrayList<>();
        plants = new ArrayList<>();
        field = new Field(depth, width);
        clock = new SimulatorClock();
        weatherHandler = new WeatherHandler(clock);
        diseaseHandler = new DiseaseHandler( field);
        producer = new AnimalFactoryProducer(field);
        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width, this);
        populationGenerator = new PopulationGenerator(view, field);

        reset();
    }

    /**
     * Sets the dashboard field to later updates the interface at the end of simulation steps.
     * 
     * @param newDashboard the dashboard to be updated.
     */
    public void setDashboard(Dashboard newDashboard) {
        this.dashboard = newDashboard;
    }

    /*///////////////////////////////////////////////////////////////
                          ECOSYSTEM SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (1000 steps).
     */
    public void runLongSimulation()
    {
        simulate(1000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * 
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            //delay(1000);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * fox and rabbit.
     */
    public void simulateOneStep()
    {
        step++;
        clock.incrementStep();
        weatherHandler.updateWeather();
        diseaseHandler.simulateDiseaseStep();

        List<Actor> newAnimals = new ArrayList<>();
        List<Actor> newPlants = new ArrayList<>();

        actorsAct(plants, newPlants);
        actorsAct(animals, newAnimals);        

        view.showStatus(step, field, clock, weatherHandler.getWeather());

        if(dashboard != null) {
            dashboard.updateDashboard();            
        }
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        animals.clear();
        plants.clear();
        populationGenerator.populate(animals, plants);

        // Show the starting state in the view.
        view.showStatus(step, field, clock, weatherHandler.getWeather());
    }

    /**
     * Iterates through a set of actors and makes them act, die if they are dead and subsequently adds the newborns.
     * 
     * @param actors List of all actors in the field.
     * @param newActors List of newborns after actors act.
     */
    private void actorsAct(List<Actor> actors, List<Actor> newActors) {
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            actor.act(newActors, weatherHandler.getWeather(), clock.getDayState());
            if(! actor.isAlive()) {
                it.remove();
            }
        }
        actors.addAll(newActors);
    }

    /**
     * Pause for a given time.
     * 
     * @param millisec The time to pause for, in milliseconds.
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
        }
    }
}

import java.util.List;
import java.util.Iterator;
import java.util.Random;
import java.lang.reflect.*;
/**
 * A class representing shared characteristics of animals.
 *
 * @version 1.3
 */
public abstract class Animal implements Actor
{

    /*///////////////////////////////////////////////////////////////
                                  STATE
    //////////////////////////////////////////////////////////////*/

    private boolean alive;
    private Field field;
    private Location location;
    protected int age;
    protected final Gender gender;
    protected int foodLevel;
    protected Integer infectionTimestamp;

    private static final Random rand = Randomizer.getRandom();
    private static final Class[] ANIMAL_CONSTRUCTOR_SIGNATURE = new Class[] {boolean.class, Field.class, Location.class, Gender.class};

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Create a new animal at location in field.
     * 
     * @param randomAge flag indicating whether to randomly generate age and foodLevel or not
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param gender Gender of the animal
     * @param baseLevel base food level of an animal
     * @param maxAge maximum age the animal can take
     */
    public Animal(boolean randomAge, Field field, Location location, Gender gender,int baseLevel, int maxAge)
    {
        if (randomAge) {
            this.age = rand.nextInt(maxAge);
            this.foodLevel = rand.nextInt(baseLevel);
        } else {
            this.foodLevel = baseLevel;
            this.age = 0;
        }
        this.alive = true;
        this.field = field;
        this.gender = gender;
        this.infectionTimestamp = null;
        setLocation(location);
    }

    /*///////////////////////////////////////////////////////////////
                            ANIMAL BEHAVIOUR LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Increments the age of the animal.
     * 
     * @param maxAge The maximum age of the animal before he dies.
     */
    protected void incrementAge(int maxAge)
    {
        age++;
        if(age > maxAge) { 
            setDead();
        }
    }

    /**
     * Increment the hunger of the animal.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();  
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newAnimals A list to receive newly born animals.
     * @param weather The current weather
     * @param dayState The different state of the day
     */
    abstract public void act(List<Actor> newAnimals, Weather weather, DayState dayState);

    /**
     * Returns the amount by which the hungerlevel would increment by if the animal were to be eaten.
     * 
     * @return the feeding value
     */
    abstract public int getFeedingValue();

    /**
     * Imitates the meeting of the animal by breeding new born animals.
     * 
     * @param newAnimals list of the animals to be born.
     * @param maxLitter the maximum amount animals that the animal can breed.
     * @param breedingProbability the likelyhood of giving birth.
     * @param breedingAge the minimum age to be able to breed.
     */
    protected void meet(List<Actor> newAnimals,int maxLitter, double breedingProbability, int breedingAge)
    {
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object obj = field.getObjectAt(where);
            if(obj == null || !this.getClass().equals(obj.getClass())) {
                continue;
            }
            Animal animal = (Animal) obj;
            if(animal.getGender() == this.getGender()) {
                continue;
            }
            try
            {
                Constructor cons = this.getClass().getConstructor(ANIMAL_CONSTRUCTOR_SIGNATURE);
                int births = breed(maxLitter, breedingProbability, breedingAge);
                giveBirth(newAnimals, births, cons);
            }
            catch (NoSuchMethodException nsme)
            {
                nsme.printStackTrace();
            }
        }
    }

    /**
     * Returns the amount of animals to breed.
     * 
     * @param maxLitter the maximum amount of animals that the animal can breed.
     * @param breedingProbability indicates the likelyhood of breeding.
     * @param breedingAge The minimum age to be able to breed.
     * @return an integer representing the amount of animals to give birth.
     */
    private int breed(int maxLitter, double breedingProbability, int breedingAge)
    {
        int births = 0;
        if(age >= breedingAge){
            double randomValue = rand.nextDouble();
            if(randomValue <= breedingProbability) {
                births = rand.nextInt(maxLitter) + 1;
            }
        }
        return births;
    }

    /**
     * Gives birth to animal by appending the animals to the input list.
     * 
     * @param newAnimals list of the new born animals.
     * @param births number of animals to give birth.
     * @param consutructor of the animals to give birth.
     */
    private void giveBirth(List<Actor> newAnimals, int births, Constructor cons)
    {
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        for (int i = 0; i < births && free.size() > 0; i++) {
            Location loc = free.remove(0);
            Gender randomGender = Utils.getRandomEnumValue(Gender.class);
            try {
                Object newObj = cons.newInstance(false, field, loc, randomGender);
                Animal newBorn = (Animal) newObj;
                newAnimals.add(newBorn);        
            } catch (InstantiationException e) {
                e.printStackTrace();
            } catch (IllegalAccessException e) {
                e.printStackTrace();
            } catch (IllegalArgumentException e) {
                e.printStackTrace();
            } catch (InvocationTargetException e) {
                e.printStackTrace();
            }
        }
    }

    /*///////////////////////////////////////////////////////////////
                          ACCESSOR AND MUTATORS
    //////////////////////////////////////////////////////////////*/

    /**
     * Accessor method for the gender of the animal.
     * 
     * @return the gender of the animal.
     */
    protected Gender getGender()
    {
        return this.gender;
    }

    /**
     * Accessor method for the timestamp of the infection.
     * 
     * @return the step at which the animal got infected.
     */
    public Integer getInfectionTimestamp()
    {
        return infectionTimestamp;
    }

    /**
     * Mutator method for the timestamp of the infection.
     * 
     * @param step The step at which the animal got infected.
     */
    public void setInfectionTimestamp(int step)
    {
        infectionTimestamp = step;
    }

    /**
     * Check whether the animal is alive or not.
     * 
     * @return true if the animal is still alive.
     */
    public boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the animal is no longer alive.
     * 
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the animal's location.
     * 
     * @return The animal's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the animal at the new location in the given field.
     * 
     * @param newLocation The animal's new location.
     */

import java.util.Random;
import java.util.List;
import java.awt.Color;
/**
 * A class responsible for generating the population,
 * as well as setting up the colours associated with each animal and plant class.
 *
 * @version 1.0
 */
public class PopulationGenerator
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // The probability that an animal will be created in any given grid position.
    private static final double FOX_CREATION_PROBABILITY = 0.09;  
    private static final double REINDEER_CREATION_PROBABILITY = 0.11;
    private static final double SHEEP_CREATION_PROBABILITY = 0.11;
    private static final double BEAR_CREATION_PROBABILITY = 0.04;
    private static final double WOLVERINE_CREATION_PROBABILITY = 0.09;
    // The probability that a plant will be created in any given grid position.
    private static final double GRASS_SPAWN_PROBABILITY = 0.09;
    private static final double SAGE_SPAWN_PROBABILITY = 0.075;
    private static final double SEDGE_SPAWN_PROBABILITY = 0.07;
    // A constant for initial number of infections in the generated population.
    private static final int INITIAL_INFECTION_COUNT = 11;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private SimulatorView view;
    private AnimalFactoryProducer producer;
    private Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Construct a population generator and set up the colours for representation of each animal class.
     */
    public PopulationGenerator(SimulatorView view, Field field)
    {
        this.view = view;
        this.field = field;
        producer = new AnimalFactoryProducer(field);
        setUpColors();
    }

    /**
     * The RGB colours associated with the given animals and plants passed to the constructor of Color class from awt library.
     */
    private void setUpColors()
    {
        view.setColor(CarnivoreFox.class, new Color(227, 93, 57));
        view.setColor(Grass.class, new Color(50, 184, 121));
        view.setColor(Sage.class, new Color(27, 117, 19));
        view.setColor(Reindeer.class, new Color(217, 162, 147));
        view.setColor(Sheep.class, Color.LIGHT_GRAY);
        view.setColor(Bear.class, new Color(112, 62, 49));
        view.setColor(Wolverine.class, Color.BLACK);
        view.setColor(Sedge.class, new Color(78, 117, 19));
        view.showColors();
    }

    /**
     * Populate the grid with animals and plants, infect the animals.
     * 
     * @param animals The list of Actor objects representing animals in the simulation
     * @param plants The list of Plant objects representing plants in the simulation
     */
    public void populate(List<Actor> animals , List<Actor> plants)
    {
      // Set up a randomizer, animal and plant factories
      Random rand = Randomizer.getRandom();
      field.clear();
      AnimalFactory herbivoreFactory = producer.getFactory(false);
      AnimalFactory carnivoreFactory = producer.getFactory(true);
      PlantFactory plantFactory = new PlantFactory(field);

      // Nested loop to go through every location on the grid and generate an animal of a certain class 
      // based on a comparison of randomised double with the creation probability of every animal
      for(int row = 0; row < field.getDepth(); row++) {
          for(int col = 0; col < field.getWidth(); col++) {
              Location location = new Location(row, col);
              if(rand.nextDouble() <= FOX_CREATION_PROBABILITY) {                  
                  animals.add(carnivoreFactory.getAnimal("FOX", location));
              }
              else if(rand.nextDouble() <= REINDEER_CREATION_PROBABILITY) {
                  animals.add(herbivoreFactory.getAnimal("SHEEP", location));
              }
              else if (rand.nextDouble() <= SHEEP_CREATION_PROBABILITY) {
                  animals.add(herbivoreFactory.getAnimal("REINDEER", location));
              }
              else if (rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
                  animals.add(carnivoreFactory.getAnimal("BEAR", location));
              }
              else if (rand.nextDouble() <= WOLVERINE_CREATION_PROBABILITY) {
                  animals.add(carnivoreFactory.getAnimal("WOLVERINE", location));
              }
                // else leave the location empty.
          }
      }

      // A loop to go through the list of generated animals and infect 11 animals
      for (int i = 0; i < INITIAL_INFECTION_COUNT; i++) {
          if (animals.get(i) instanceof Animal){
              Animal animal = (Animal) (animals.get(i));
              animal.setInfectionTimestamp(0);
          }    
      }

      // Nested loop to go through every location on the grid and generate a plant of a certain class 
      // based on a comparison of randomised double with the creation probability of every plant
      for(int row = 0; row < field.getDepth(); row++) {
          for(int col = 0; col < field.getWidth(); col++) {
              Location location = new Location(row, col);
              if(rand.nextDouble() <= GRASS_SPAWN_PROBABILITY) {                    
                  plants.add(plantFactory.getPlant("GRASS", location));
              }
              else if(rand.nextDouble() <= SAGE_SPAWN_PROBABILITY) {
                  plants.add(plantFactory.getPlant("SAGE", location));
              }
              else if(rand.nextDouble() <= SEDGE_SPAWN_PROBABILITY) {
                    plants.add(plantFactory.getPlant("SEDGE", location));
              }
                // else leave the location empty.
            }
        }
    } 
}

import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;
import java.util.ArrayList;
/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single animal.
 *
 * @version 2016.02.29
 */
public class Field
{

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();
    // the dimensions for the grids
    private final int depth, width;

    /*///////////////////////////////////////////////////////////////
                               ACTOR STORAGE
    //////////////////////////////////////////////////////////////*/

    private Object[][] field;
    private Plant [][] terrain;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        field = new Object[depth][width];
        terrain = new Plant[depth][width];
    }

    /*///////////////////////////////////////////////////////////////
                            ANIMAL FIELD LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                field[row][col] = null;
                terrain[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * 
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location, it will be lost.
     * 
     * @param animal The animal to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object animal, int row, int col)
    {
        place(animal, new Location(row, col));
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will be lost.
     * 
     * @param animal The animal to be placed.
     * @param location Where to place the animal.
     */
    public void place(Object animal, Location location)
    {
        field[location.getRow()][location.getCol()] = animal;
    }

    /**
     * Return the animal at the given location, if any.
     * 
     * @param location Where in the field.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the animal at the given location, if any.
     * 
     * @param row The desired row.
     * @param col The desired column.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * 
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        return getFreeAdjacent(field, location);
    }

    /**
     * Groups animals that are contained within the same 20 by 20 block within the main animal field.
     * 
     * @return List of animals contained within the same block.
     */
    public List<List<Animal>> getAnimalsPerBlock()
    {
        List<List<Animal>> blocks = new ArrayList<>();
        for(int i = 0 ; i < width; i+= 20){
            for (int j = 0; j < depth; j+= 20) {
                List<Animal> animals = new ArrayList<>();
                for (int k = i; k < i + 20; k++) {
                    for(int l = j; l < j + 20; l++) {
                        Object obj = getObjectAt(l, k);
                        if(obj instanceof Animal) {
                            animals.add((Animal) obj);
                        }
                    }
                }
                blocks.add(animals);
            }
        }
        return blocks;
    }

    /*///////////////////////////////////////////////////////////////
                            PLANT TERRAIN LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Clear the given location.
     * 
     * @param location The location to clear.
     */

    public void clearPlant(Location location)
    {
        terrain[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place a plant at the given location.
     * If there is already a plant at the location it will be lost.
     * 
     * @param animal The animal to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void placePlant(Plant plant, int row, int col)
    {
        placePlant(plant, new Location(row, col));
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will be lost.
     * 
     * @param animal The animal to be placed.
     * @param location location to place the animal at
     */
    public void placePlant(Plant plant, Location location)
    {
        terrain[location.getRow()][location.getCol()] = plant;
    }

    /**
     * Return the plant at the given location, if any.
     * 
     * @param the desired location.
     * @return The plant at the given location, or null if there is none.
     */    
    public Plant getPlantAt(Location location)
    {
        return getPlantAt(location.getRow(), location.getCol());
    }

    /**
     * Return the animal at the given location, if any.
     * 
     * @param row The desired row.
     * @param col The desired column.
     * @return The animal at the given location, or null if there is none.
     */
    public Plant getPlantAt(int row, int col)
    {
        return terrain[row][col];
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * 
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentTerrain(Location location)
    {
        return getFreeAdjacent(terrain, location);
    }

    /*///////////////////////////////////////////////////////////////
                            GRID AGNOSTIC LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * 
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Given a grid and a location, returns the free adjacent location within that grid.
     * 
     * @param grid A 2 dimensional storage space to store actors.
     * @params location the location to seek the adjacents for.
     */
    private List<Location> getFreeAdjacent(Object[][] grid, Location location) 
    {

     * The returned location will be within the valid bounds
     * of the field.
     * 
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Given a grid and a location, returns the free adjacent location within that grid.
     * 
     * @param grid A 2 dimensional storage space to store actors.
     * @params location the location to seek the adjacents for.
     */
    private List<Location> getFreeAdjacent(Object[][] grid, Location location) 
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for (Location loc : adjacent) {
            if(grid[loc.getRow()][loc.getCol()] == null) {
                free.add(loc);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * 
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * 
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }
            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * 
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * 
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
}

    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the animal's field.
     * 
     * @return The animal's field.
     */
    protected Field getField()
    {
        return field;
    }
}

import java.util.TreeMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Random;
/**
 * Class responsible for handling the simulation of the disease.
 *
 * @version 1.0
 */
public class DiseaseHandler
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // cooldown before the animal achieves natural immunity
    private static final int DISINFECTION_DURATION = 5;
    private final Random rand = Randomizer.getRandom();
    private final Field field;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    public static TreeMap<Integer, Integer> count;
    private int currentStep;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a new disease handler
     * @param field The field to later get the animals per block and compute the density
     */
    public DiseaseHandler(Field field)
    {
        count = new TreeMap<>();
        this.field = field;
        currentStep = 0;
    }

    /*///////////////////////////////////////////////////////////////
                          DISEASE SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Simulates the disease by iterating through every block in the field, and computing the density of the number of ppl infected 
     * in the given block to determine the likelyhood of being infected in the block
     */
    public void simulateDiseaseStep()
    {
        // fetch the animal per blocks eg : [block1 : [animal1,animal2, animal3]. block 2: [animal1, animal 2, animal3]...]
        List<List<Animal>> blocks = field.getAnimalsPerBlock();
        int infectionCount = 0;
        currentStep++;
        for (List<Animal> block : blocks) {
            int densityIndex = 0;
            List<Animal> uninfectedAnimals = new ArrayList<>();
            for(Animal animal : block) {
                if(animal.getInfectionTimestamp() != null && currentStep - animal.getInfectionTimestamp() < DISINFECTION_DURATION) {
                    // increase the counter of number of animals infected within this block.
                    densityIndex++;
                    continue;
                }
                if(animal.getInfectionTimestamp() == null) {
                    uninfectedAnimals.add(animal);
                }
            }
            // compute probability of being infected.
            double pValue = (double)((double)densityIndex/(double)block.size());
            for(Animal animal : uninfectedAnimals) {
                double randNumber = rand.nextDouble();
                if(randNumber < pValue ) {
                    animal.setInfectionTimestamp(currentStep);
                }
            }
            infectionCount += densityIndex;
        }
        count.put(currentStep, infectionCount);
    }
}

