138	     * @param maxLitter the maximum amount of animals that the animal can breed.
139	     * @param breedingProbability indicates the likelyhood of breeding.
140	     * @param breedingAge The minimum age to be able to breed.
141	     * @return an integer representing the amount of animals to give birth.
142	     */
143	    private int breed(int maxLitter, double breedingProbability, int breedingAge)
144	    {
145	        int births = 0;
146	        if(age >= breedingAge){
147	            double randomValue = rand.nextDouble();
148	            if(randomValue <= breedingProbability) {
149	                births = rand.nextInt(maxLitter) + 1;
150	            }
151	        }
152	        return births;
153	    }
