156	     * Gives birth to animal by appending the animals to the input list.
157	     * 
158	     * @param newAnimals list of the new born animals.
159	     * @param births number of animals to give birth.
160	     */
161	    private void giveBirth(List<Actor> newAnimals, int births)
162	    {
163	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
164	        for (int i = 0; i < births && free.size() > 0; i++) {
165	            Location loc = free.remove(0);
166	            Gender randomGender = Utils.getRandomEnumValue(Gender.class);
167	            Animal newBorn = getSpecies().createYoung(field, loc, randomGender);
168	            newAnimals.add(newBorn);
169	        }
170	    }
