 57	    /**
 58	     * Create a simulation field with the given size.
 59	     * 
 60	     * @param depth Depth of the field. Must be greater than zero.
 61	     * @param width Width of the field. Must be greater than zero.
 62	     */
 63	    public Simulator(int depth, int width) throws Exception
 64	    {
 65	        if(depth % 20 != 0 || width % 20 != 0) {
 66	            throw new Exception("Depth and Width must be factors of 20");
 67	        }
 68	        
 69	        if(width <= 0 || depth <= 0) {
 70	            depth = DEFAULT_DEPTH;
 71	            width = DEFAULT_WIDTH;
 72	        }
 73	        
 74	        animals = new ArrayList<>();
 75	        plants = new ArrayList<>();
 76	        field = new Field(depth, width);
 77	        clock = new SimulatorClock();
 78	        weatherHandler = new WeatherHandler(clock);
 79	        diseaseHandler = new DiseaseHandler( field);
 80	        // Create a view of the state of each location in the field.
 81	        view = new SimulatorView(depth, width, this);
 82	        populationGenerator = new PopulationGenerator(view, field);
 83	        
 84	        reset();
 85	    }
 86	    
 87	    /**
 88	     * Sets the dashboard field to later updates the interface at the end of simulation steps.
