 96	    /*///////////////////////////////////////////////////////////////
 97	                          ECOSYSTEM SIMULATION LOGIC
 98	    //////////////////////////////////////////////////////////////*/
 99	    
100	    /**
101	     * Run the simulation from its current state for a reasonably long period,
102	     * (1000 steps).
103	     */
104	    public void runLongSimulation()
105	    {
106	        simulate(1000);
107	    }
108	    
109	    /**
110	     * Run the simulation from its current state for the given number of steps.
111	     * Stop before the given number of steps if it ceases to be viable.
112	     * 
113	     * @param numSteps The number of steps to run for.
114	     */
115	    public void simulate(int numSteps)
116	    {
117	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
118	            simulateOneStep();
119	            //delay(1000);   // uncomment this to run more slowly
120	        }
121	    }
122	    
123	    /**
124	     * Run the simulation from its current state for a single step.
125	     * Iterate over the whole field updating the state of each
126	     * fox and rabbit.
127	     */
128	    public void simulateOneStep()
129	    {
130	        step++;
131	        clock.incrementStep();
132	        weatherHandler.updateWeather();
133	        diseaseHandler.simulateDiseaseStep();
134	        
135	        List<Actor> newAnimals = new ArrayList<>();
136	        List<Actor> newPlants = new ArrayList<>();
137	        
138	        actorsAct(plants, newPlants);
139	        actorsAct(animals, newAnimals);        
140	        
141	        view.showStatus(step, field, clock, weatherHandler.getWeather());
142	
143	        if(dashboard != null) {
144	            dashboard.updateDashboard();            
145	        }
146	    }
147	        
148	    /**
149	     * Reset the simulation to a starting position.
150	     */
151	    public void reset()
152	    {
153	        step = 0;
154	        animals.clear();
155	        plants.clear();
156	        populationGenerator.populate(animals, plants);
157	        
158	        // Show the starting state in the view.
159	        view.showStatus(step, field, clock, weatherHandler.getWeather());
160	    }
161	    
162	    /**
163	     * Iterates through a set of actors and makes them act, die if they are dead and subsequently adds the newborns.
164	     * 
165	     * @param actors List of all actors in the field.
166	     * @param newActors List of newborns after actors act.
167	     */
168	    private void actorsAct(List<Actor> actors, List<Actor> newActors) {
169	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
170	            Actor actor = it.next();
171	            actor.act(newActors, weatherHandler.getWeather(), clock.getDayState());
172	            if(! actor.isAlive()) {
173	                it.remove();
174	            }
175	        }
176	        actors.addAll(newActors);
177	    }
