  3	/**
  4	 * A blueprint for how a typical plant behaves. A plant grows according to the weather 
  5	 * conditions and daylight, and feeds more as it grows.
  6	 *
  7	 * @version 1.0
  8	 */
  9	public abstract class Plant implements Actor
 10	{
 11	    
 12	    /*///////////////////////////////////////////////////////////////
 13	                                  STATE
 14	    //////////////////////////////////////////////////////////////*/
 15	    
 16	    private static final int FEEDING_FACTOR = 2;
 17	    protected boolean alive;
 18	    protected Location location;
 19	    protected int age;
 20	    protected int health;
 21	    protected int feedingValue; 
 22	    protected Field field;
 23	     
 24	    private static final Random rand = Randomizer.getRandom();
 25	    
 26	    /*///////////////////////////////////////////////////////////////
 27	                                CONSTRUCTOR
 28	    //////////////////////////////////////////////////////////////*/
 29	    
 30	    /**
 31	     * Creates a plant.
 32	     * 
 33	     * @param randomAge Boolean flag denoting whether or not to randomly generate an age for this plant
 34	     * @param field The field currently occupied
 35	     * @param location The location of the plant
 36	     * @param maxAge The maximum age the plant can take
 37	     */
 38	    public Plant(boolean randomAge,Field field, Location location, int maxAge) 
 39	    {
 40	        if(randomAge) {
 41	            this.age = rand.nextInt(maxAge);
 42	            this.feedingValue = age * FEEDING_FACTOR;
 43	        } else {
 44	            this.age = 0;
 45	            this.feedingValue = 0;
 46	        }
 47	        this.alive = true;
 48	        this.field = field;
 49	        setLocation(location);
 50	    }
 51	    
 52	    /*///////////////////////////////////////////////////////////////
 53	                            PLANT BEHAVIOUR LOGIC
 54	    //////////////////////////////////////////////////////////////*/
 55	    
 56	    /**
 57	     * Make this plant act - that is: make it do
 58	     * whatever it wants/needs to do.
 59	     * 
 60	     * @param newPlants A list to receive newly generated plants.
 61	     * @param weather The current weather
 62	     * @param dayState The different state of the day
 63	     */
 64	    
 65	    public abstract void act(List<Actor> newPlants, Weather weather, DayState dayState);
 66	
 67	    /**
 68	     * Returns the species definition for this plant.
 69	     *
 70	     * @return the current plant species.
 71	     */
 72	    protected abstract PlantSpecies getSpecies();
 73	    
 74	    /**
 75	     * Increments the age of the plant.
 76	     * 
 77	     * @param maxAge The maximum age a plant can take.
 78	     */
 79	    private void incrementAge(int maxAge) {
 80	        age++;
 81	        if(age > maxAge) {
 82	            setDead();
 83	        }
 84	    }
 85	    
 86	    /**
 87	     * Updates how much the plant will feed if it is to be eaten.
 88	     */
 89	    private void updateFeedingValue()
 90	    {
 91	        this.feedingValue = age * FEEDING_FACTOR;
 92	    }
 93	    
 94	    /**
 95	     * Updates the age and how much the plant will feed.
 96	     * 
 97	     * @param maxAge The maximum age a plant can take.
 98	     */
 99	    protected void grow(int maxAge)
100	    {
101	        incrementAge(maxAge);
102	        updateFeedingValue();
103	    }
104	    
105	    /**
106	     * Imitates the spread/growth of a plant.
107	     * 
108	     * @param spreadProbability likelihood a spreading to the next cell.
109	     * @param newPlants the newly generated plants.
110	     */
111	    protected void multiply(double spreadProbability, List<Actor> newPlants)
112	    {
113	        List<Location> freeLocs = field.getFreeAdjacentTerrain(location);
114	        for ( Location loc : freeLocs) {
115	            if(rand.nextDouble() < spreadProbability) {
116	                Plant plant = getSpecies().createYoung(field, loc);
117	                newPlants.add(plant);
118	            }
119	        }
120	    }
