136	    /**
137	     * Accessor method for the feeding value of the plant.
138	     * 
139	     * @return the feeding value of the plant.
140	     */
141	    public int getFeedingValue()
142	    {
143	        return feedingValue;
144	    }
145	    
146	    /**
147	     * Mutator method for the location of the plant.
148	     * 
149	     * @param newLocation the new location to be set.
150	     */
151	    protected void setLocation(Location newLocation)
152	    {
153	        if(location != null) {
154	            field.clearPlant(location);
155	        }
156	        location = newLocation;
157	        field.placePlant(this, newLocation);
158	    }
