160	    /**
161	     * Sets the plant dead and removes all references to it, as well as its storage.
162	     */
163	    protected void setDead()
164	    {
165	        alive = false;
166	        if(location != null) {
167	            //errain.clear(location);
168	            field.clearPlant(location);
169	            location = null;
170	            field = null;
171	        }
172	    }
