  1	import java.util.Random;
  2	import java.util.List;
  3	/**
  4	 * A class responsible for generating the population,
  5	 * as well as setting up the colours associated with each animal and plant class.
  6	 *
  7	 * @version 1.0
  8	 */
  9	public class PopulationGenerator
 10	{
 11	    
 12	    /*///////////////////////////////////////////////////////////////
 13	                                 CONSTANTS
 14	    //////////////////////////////////////////////////////////////*/
 15	    
 16	    // A constant for initial number of infections in the generated population.
 17	    private static final int INITIAL_INFECTION_COUNT = 11;
 18	    private static final AnimalSpecies[] ANIMAL_SPAWN_ORDER = {
 19	        AnimalSpecies.FOX,
 20	        AnimalSpecies.REINDEER,
 21	        AnimalSpecies.SHEEP,
 22	        AnimalSpecies.BEAR,
 23	        AnimalSpecies.WOLVERINE
 24	    };
 25	    private static final PlantSpecies[] PLANT_SPAWN_ORDER = {
 26	        PlantSpecies.GRASS,
 27	        PlantSpecies.SAGE,
 28	        PlantSpecies.SEDGE
 29	    };
 30	    
 31	    /*///////////////////////////////////////////////////////////////
 32	                                   STATE
 33	    //////////////////////////////////////////////////////////////*/
 34	    
 35	    private final SimulatorView view;
 36	    private final AnimalFactory animalFactory;
 37	    private final PlantFactory plantFactory;
 38	    private final Field field;
 39	    
 40	    /*///////////////////////////////////////////////////////////////
 41	                                CONSTRUCTOR
 42	    //////////////////////////////////////////////////////////////*/
 43	    
 44	    /**
 45	     * Construct a population generator and set up the colours for representation of each animal class.
 46	     */
 47	    public PopulationGenerator(SimulatorView view, Field field)
 48	    {
 49	        this.view = view;
 50	        this.field = field;
 51	        animalFactory = new AnimalFactory(field);
 52	        plantFactory = new PlantFactory(field);
 53	        setUpColors();
 54	    }
 55	    
 56	    /**
 57	     * The RGB colours associated with the given animals and plants passed to the constructor of Color class from awt library.
 58	     */
 59	    private void setUpColors()
 60	    {
 61	        for (AnimalSpecies species : AnimalSpecies.values()) {
 62	            view.setColor(species.getActorClass(), species.getColor());
 63	        }
 64	        for (PlantSpecies species : PlantSpecies.values()) {
 65	            view.setColor(species.getActorClass(), species.getColor());
 66	        }
 67	        view.showColors();
 68	    }
 69	    
 70	    /**
 71	     * Populate the grid with animals and plants, infect the animals.
 72	     * 
 73	     * @param animals The list of Actor objects representing animals in the simulation
 74	     * @param plants The list of Plant objects representing plants in the simulation
 75	     */
 76	    public void populate(List<Actor> animals , List<Actor> plants)
 77	    {
 78	        field.clear();
 79	        populateAnimals(animals);
 80	        infectInitialAnimals(animals);
 81	        populatePlants(plants);
 82	    }
 83	
 84	    private void populateAnimals(List<Actor> animals)
 85	    {
 86	        Random rand = Randomizer.getRandom();
 87	        for(int row = 0; row < field.getDepth(); row++) {
 88	            for(int col = 0; col < field.getWidth(); col++) {
 89	                Location location = new Location(row, col);
 90	                Animal animal = createAnimalAt(rand, location);
 91	                if(animal != null) {
 92	                    animals.add(animal);
 93	                }
 94	            }
 95	        }
 96	    }
 97	
 98	    private void infectInitialAnimals(List<Actor> animals)
 99	    {
100	        int infectedCount = Math.min(INITIAL_INFECTION_COUNT, animals.size());
101	        for (int i = 0; i < infectedCount; i++) {
102	            if (animals.get(i) instanceof Animal){
103	                Animal animal = (Animal) animals.get(i);
104	                animal.setInfectionTimestamp(0);
105	            }
106	        }
107	    }
108	
109	    private void populatePlants(List<Actor> plants)
110	    {
111	        Random rand = Randomizer.getRandom();
112	        for(int row = 0; row < field.getDepth(); row++) {
113	            for(int col = 0; col < field.getWidth(); col++) {
114	                Location location = new Location(row, col);
115	                Plant plant = createPlantAt(rand, location);
116	                if(plant != null) {
117	                    plants.add(plant);
118	                }
119	            }
120	        }
121	    }
122	
123	    private Animal createAnimalAt(Random rand, Location location)
124	    {
125	        for (AnimalSpecies species : ANIMAL_SPAWN_ORDER) {
126	            if(rand.nextDouble() <= species.getSpawnProbability()) {
127	                return animalFactory.create(species, location);
128	            }
129	        }
130	        return null;
131	    }
132	
133	    private Plant createPlantAt(Random rand, Location location)
134	    {
135	        for (PlantSpecies species : PLANT_SPAWN_ORDER) {
136	            if(rand.nextDouble() <= species.getSpawnProbability()) {
137	                return plantFactory.create(species, location);
138	            }
139	        }
140	        return null;
141	    }
142	}
